"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Wallet, ArrowRight, Mail, Lock } from "lucide-react";

export default function LoginPage() {
  const router = useRouter();
  const [form, setForm] = useState({ email: "", password: "" });
  const [error, setError] = useState("");

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.email || !form.password) {
      setError("Por favor ingresa tu correo y contraseña.");
      return;
    }

    // Buscar si existe un usuario registrado en localStorage
    const savedUser = localStorage.getItem("gastos-user");
    
    if (!savedUser) {
      setError("No hay ninguna cuenta registrada. Por favor regístrate primero.");
      return;
    }

    const user = JSON.parse(savedUser);

    // Verificar si el correo y la contraseña coinciden exactamente
    if (user.email !== form.email || user.password !== form.password) {
      setError("Correo o contraseña incorrectos.");
      return;
    }

    // Si todo es correcto, guardamos la sesión y entramos al dashboard
    localStorage.setItem("gastos-logged", "true");
    router.push("/dashboard");
  };

  return (
    <div className="flex min-h-screen flex-col items-center justify-center px-4 py-12 selection:bg-primary selection:text-primary-foreground">
      <div className="w-full max-w-md space-y-8 rounded-3xl border border-border bg-card p-8 backdrop-blur-xl shadow-2xl animate-fade-up">
        <div className="flex flex-col items-center text-center">
          <div className="grid h-14 w-14 place-items-center rounded-2xl border border-primary/40 bg-primary/15 shadow-[0_0_24px_-6px_var(--primary)] mb-4">
            <Wallet className="h-7 w-7 text-primary" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight">Bienvenido de nuevo</h1>
          <p className="text-sm text-muted-foreground mt-1">Ingresa a tu cuenta para gestionar tus gastos.</p>
        </div>

        {error && (
          <div className="rounded-xl border border-destructive/40 bg-destructive/10 p-3 text-center text-sm font-medium text-destructive">
            {error}
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Correo electrónico</label>
            <div className="flex items-center gap-2 rounded-xl border border-input bg-secondary/40 px-3 py-3 transition focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/30">
              <Mail className="h-4 w-4 text-muted-foreground" />
              <input
                type="email"
                placeholder="tu@correo.com"
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground/50"
              />
            </div>
          </div>

          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Contraseña</label>
            <div className="flex items-center gap-2 rounded-xl border border-input bg-secondary/40 px-3 py-3 transition focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/30">
              <Lock className="h-4 w-4 text-muted-foreground" />
              <input
                type="password"
                placeholder="••••••••"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground/50"
              />
            </div>
          </div>

          <button
            type="submit"
            className="w-full flex items-center justify-center gap-2 rounded-xl bg-primary py-3.5 font-semibold text-primary-foreground shadow-lg shadow-primary/30 transition hover:scale-[1.02]"
          >
            Iniciar sesión <ArrowRight className="h-4 w-4" />
          </button>
        </form>

        <p className="text-center text-sm text-muted-foreground">
          ¿No tienes una cuenta?{" "}
          <Link href="/register" className="font-semibold text-primary hover:underline">
            Regístrate gratis
          </Link>
        </p>
      </div>
    </div>
  );
}